import{_ as c,o as t,c as h,a2 as i}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Chương trình Cơ bản về Tiến bộ Chung của Muôn tộc","description":"","frontmatter":{},"headers":[],"relativePath":"vi/05-万族共进基本纲领.md","filePath":"vi/05-万族共进基本纲领.md","lastUpdated":1789183869000}'),g={name:"vi/05-万族共进基本纲领.md"};function a(u,n,o,r,d,l){return t(),h("div",null,[...n[0]||(n[0]=[i('<h1 id="chuong-trinh-co-ban-ve-tien-bo-chung-cua-muon-toc" tabindex="-1">Chương trình Cơ bản về Tiến bộ Chung của Muôn tộc <a class="header-anchor" href="#chuong-trinh-co-ban-ve-tien-bo-chung-cua-muon-toc" aria-label="Permalink to &quot;Chương trình Cơ bản về Tiến bộ Chung của Muôn tộc&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>05</td></tr><tr><td>Mô-đun</td><td>Nguyên tắc chung và Cài đặt cốt lõi</td></tr><tr><td>Từ khóa chính</td><td>Muôn tộc, Tiến bộ chung, Bình đẳng chủng tộc, Tiến hóa hợp tác, Cộng hòa</td></tr></tbody></table><h2 id="_1-đinh-nghia-va-pham-vi-cua-muon-toc" tabindex="-1">1. Định nghĩa và Phạm vi của Muôn tộc <a class="header-anchor" href="#_1-đinh-nghia-va-pham-vi-cua-muon-toc" aria-label="Permalink to &quot;1. Định nghĩa và Phạm vi của Muôn tộc&quot;">​</a></h2><p>&quot;Muôn tộc&quot; là tên gọi chung cho tất cả các dạng sống có tiềm năng tri giác và tiến hóa trong Vũ trụ Nguyên bản của Muôn linh và Neo cân bằng. &quot;Muôn&quot; không chỉ chính xác là mười nghìn chủng tộc, mà là cách nói cực đoan về số lượng lớn, bao gồm tất cả các dạng sống đã biết và chưa biết. Phạm vi của Muôn tộc bao gồm, nhưng không giới hạn ở: Người tộc và các chủng tộc giống người khác, dạng sống năng lượng, thực thể ý thức, dạng sống cơ khí, dạng sống thông minh kiểu thực vật, dạng sống dị thường, chủng tộc lai giữa các vị diện, v.v.</p><p>Văn minh cộng sinh kiên trì nguyên tắc &quot;bình đẳng các dạng sống&quot;, không sử dụng cấu tạo vật chất, mức độ năng lượng, hay độ phức tạp ý thức của sự sống làm tiêu chuẩn để phân chia cao-thấp, quý-hèn. Bất kỳ chủng tộc nào, bất kể mức độ cảnh giới tu luyện trung bình của cá thể, số lượng dân số, hay chiều dài lịch sử của nó, đều hưởng địa vị và quyền lợi bình đẳng trong văn minh cộng sinh.</p><h2 id="_2-tu-tuong-cot-loi-cua-tien-bo-chung-muon-toc" tabindex="-1">2. Tư tưởng cốt lõi của Tiến bộ chung Muôn tộc <a class="header-anchor" href="#_2-tu-tuong-cot-loi-cua-tien-bo-chung-muon-toc" aria-label="Permalink to &quot;2. Tư tưởng cốt lõi của Tiến bộ chung Muôn tộc&quot;">​</a></h2><p>Tiến bộ chung Muôn tộc là một trong những mục tiêu cốt lõi của Văn minh Cộng sinh Neo, và tư tưởng cơ bản của nó có thể được tóm tắt trong bốn điểm sau:</p><ol><li><strong>Tiến hóa không phải là trò chơi tổng bằng không giữa các chủng tộc</strong>: Tiến hóa của một chủng tộc không phải trả giá bằng sự hy sinh của các chủng tộc khác; ngược lại, sự hợp tác giữa các chủng tộc có thể tạo ra hiệu ứng tiến hóa hiệp đồng.</li><li><strong>Mỗi chủng tộc đều có ưu thế tiến hóa độc đáo</strong>: Các chủng tộc khác nhau đã hình thành đặc điểm và thiên tài riêng của mình trong quá trình tiến hóa dài, và những đặc điểm này là tài sản quý giá cho sự đa dạng tiến hóa của vũ trụ.</li><li><strong>Chủng tộc lạc hậu có quyền được hỗ trợ</strong>: Đối với các chủng tộc có mức độ tiến hóa thấp hơn, văn minh cộng sinh có nghĩa vụ cung cấp hỗ trợ về giáo dục, tài nguyên, công nghệ, v.v., giúp họ tìm ra con đường tiến hóa phù hợp với bản thân.</li><li><strong>Chủng tộc tiên tiến có nghĩa vụ gánh vác trách nhiệm</strong>: Các chủng tộc có mức độ tiến hóa cao hơn gánh vác nhiều trách nhiệm công cộng hơn trong văn minh cộng sinh, bao gồm bảo trì Điểm Neo, kế thừa tri thức, bảo vệ văn minh, v.v.</li></ol><h2 id="_3-nguyen-tac-co-ban-cua-tien-bo-chung-muon-toc" tabindex="-1">3. Nguyên tắc cơ bản của Tiến bộ chung Muôn tộc <a class="header-anchor" href="#_3-nguyen-tac-co-ban-cua-tien-bo-chung-muon-toc" aria-label="Permalink to &quot;3. Nguyên tắc cơ bản của Tiến bộ chung Muôn tộc&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Nội hàm</th><th>Yêu cầu cụ thể</th></tr></thead><tbody><tr><td>Nguyên tắc bình đẳng chủng tộc</td><td>Tất cả các chủng tộc đều bình đẳng về địa vị pháp lý và quyền tiến hóa</td><td>Cấm phân biệt đối xử chủng tộc, chức vụ công cộng mở cửa cho tất cả các chủng tộc</td></tr><tr><td>Nguyên tắc tôn trọng văn hóa</td><td>Tôn trọng truyền thống văn hóa và lối sống của mỗi chủng tộc</td><td>Không cưỡng bức đồng hóa văn hóa, hỗ trợ kế thừa và phát triển văn hóa chủng tộc</td></tr><tr><td>Nguyên tắc bổ sung ưu thế</td><td>Khuyến khích các chủng tộc phát huy ưu thế riêng để hợp tác</td><td>Xây dựng cơ sở dữ liệu chuyên môn chủng tộc, thúc đẩy các dự án hợp tác giữa các chủng tộc</td></tr><tr><td>Nguyên tắc hỗ trợ lạc hậu</td><td>Cung cấp hỗ trợ bổ sung cho các chủng tộc có mức độ tiến hóa thấp hơn</td><td>Thành lập quỹ phát triển chủng tộc, cung cấp giáo dục định hướng và phân bổ tài nguyên</td></tr><tr><td>Nguyên tắc tự trị và đồng trị</td><td>Việc nội bộ chủng tộc tự trị, việc giữa các chủng tộc đồng trị</td><td>Mỗi chủng tộc có quyền lập pháp nội bộ, việc công cộng do thể chế cộng hòa quyết định</td></tr><tr><td>Nguyên tắc giải quyết xung đột hòa bình</td><td>Xung đột giữa các chủng tộc được giải quyết bằng cách hòa bình</td><td>Cấm chiến tranh giữa các chủng tộc, xung đột được nộp cho Tòa án Neo trọng tài</td></tr></tbody></table><h2 id="_4-đuong-loi-thuc-hien-tien-bo-chung-muon-toc" tabindex="-1">4. Đường lối thực hiện Tiến bộ chung Muôn tộc <a class="header-anchor" href="#_4-đuong-loi-thuc-hien-tien-bo-chung-muon-toc" aria-label="Permalink to &quot;4. Đường lối thực hiện Tiến bộ chung Muôn tộc&quot;">​</a></h2><p>Tiến bộ chung Muôn tộc không phải là một khẩu hiệu, mà được thực hiện từng bước thông qua các đường lối cụ thể sau:</p><h3 id="_4-1-giao-duc-chung" tabindex="-1">4.1 Giáo dục chung <a class="header-anchor" href="#_4-1-giao-duc-chung" aria-label="Permalink to &quot;4.1 Giáo dục chung&quot;">​</a></h3><p>Xây dựng hệ thống giáo dục cộng sinh giữa các chủng tộc, nơi thanh thiếu niên của tất cả các chủng tộc có thể nhận giáo dục tiến hóa cơ bản miễn phí. Nội dung giáo dục bao gồm các pháp môn cơ bản của Ba trăm hệ tu luyện, đạo đức chống cướp bóc, Hiến chương Văn minh Cộng sinh, kiến thức phổ thông vũ trụ, v.v. Đồng thời tôn trọng truyền thống giáo dục văn hóa của mỗi chủng tộc, cho phép tổ chức giáo dục có đặc sắc chủng tộc ngoài giáo dục chung.</p><h3 id="_4-2-chia-se-tai-nguyen" tabindex="-1">4.2 Chia sẻ tài nguyên <a class="header-anchor" href="#_4-2-chia-se-tai-nguyen" aria-label="Permalink to &quot;4.2 Chia sẻ tài nguyên&quot;">​</a></h3><p>Thông qua cơ chế hợp đồng liên sản, phân bổ tổng hợp tài nguyên tu luyện vũ trụ theo dân số chủng tộc, nhu cầu tiến hóa và mức độ đóng góp. Đối với các chủng tộc thiếu tài nguyên, thực hiện điều phối tài nguyên giữa các vị diện thông qua mạng lưới Điểm Neo. Cấm bất kỳ chủng tộc nào độc quyền tài nguyên tu luyện công cộng.</p><h3 id="_4-3-nghien-cuu-cong-nghe-chung" tabindex="-1">4.3 Nghiên cứu công nghệ chung <a class="header-anchor" href="#_4-3-nghien-cuu-cong-nghe-chung" aria-label="Permalink to &quot;4.3 Nghiên cứu công nghệ chung&quot;">​</a></h3><p>Khuyến khích nghiên cứu hợp tác công nghệ giữa các chủng tộc, đặc biệt là các dự án nghiên cứu kết hợp năng lực thiên phú của các chủng tộc khác nhau với kỹ thuật pháp tắc. Văn minh cộng sinh thành lập &quot;Quỹ Nghiên cứu chung Muôn tộc&quot;, tài trợ cho các đội ngũ nghiên cứu giữa các chủng tộc. Kết quả nghiên cứu được mở miễn phí cho tất cả các chủng tộc.</p><h3 id="_4-4-luu-chuyen-nhan-tai" tabindex="-1">4.4 Lưu chuyển nhân tài <a class="header-anchor" href="#_4-4-luu-chuyen-nhan-tai" aria-label="Permalink to &quot;4.4 Lưu chuyển nhân tài&quot;">​</a></h3><p>Phá vỡ các rào cản nhân tài giữa các chủng tộc, cho phép tu luyện giả lưu chuyển và trao đổi tự do giữa các khu vực định cư của các chủng tộc khác nhau. Xây dựng hệ thống cố vấn giữa các chủng tộc, nơi tu luyện giả cấp cao có thể hướng dẫn tu luyện giả sơ cấp của các chủng tộc khác.</p><h3 id="_4-5-tham-gia-cong-hoa" tabindex="-1">4.5 Tham gia cộng hòa <a class="header-anchor" href="#_4-5-tham-gia-cong-hoa" aria-label="Permalink to &quot;4.5 Tham gia cộng hòa&quot;">​</a></h3><p>Nghị viện Cộng hòa Muôn tộc phân bổ ghế tổng hợp theo dân số chủng tộc và mức độ đóng góp, đảm bảo các chủng tộc nhỏ cũng có kênh lên tiếng. Quyết định của nghị viện áp dụng cách kết hợp đồng thuận thông qua đàm phán và bỏ phiếu đa số, và các vấn đề liên quan đến lợi ích cốt lõi của một chủng tộc phải được sự đồng ý của chủng tộc liên quan.</p><h2 id="_5-chinh-sach-đoi-voi-cac-chung-toc-đac-biet" tabindex="-1">5. Chính sách đối với các chủng tộc đặc biệt <a class="header-anchor" href="#_5-chinh-sach-đoi-voi-cac-chung-toc-đac-biet" aria-label="Permalink to &quot;5. Chính sách đối với các chủng tộc đặc biệt&quot;">​</a></h2><p>Đối với các chủng tộc trong tình huống đặc biệt, văn minh cộng sinh áp dụng các chính sách khác biệt:</p><ul><li><strong>Chủng tộc có nguy cơ tuyệt chủng</strong>: Thành lập kế hoạch bảo tồn chủng tộc, cung cấp hỗ trợ tài nguyên khẩn cấp và bảo tồn môi trường sống, giúp họ phục hồi quần thể</li><li><strong>Chủng tộc dạng sống dị thường</strong>: Đánh giá và an đặt theo quy trình xử lý tiêu chuẩn hóa ba loại dạng sống dị thường, đảm bảo quyền tiến hóa của họ được bảo vệ</li><li><strong>Chủng tộc lai giữa các vị diện</strong>: Công nhận danh tính chủng tộc kép của họ, bảo đảm quyền bình đẳng của họ trong cả hai nền văn hóa chủng tộc</li><li><strong>Chủng tộc cướp bóc trước đây</strong>: Đối với các chủng tộc đã theo chủ nghĩa cướp bóc trong lịch sử, sau khi hoàn thành cải tạo đạo đức và chuyển hóa hệ thống, trao địa vị hoàn toàn bình đẳng, không thực hiện phân biệt đối xử hồi tố lịch sử</li></ul><h2 id="_6-chi-so-đo-luong-tien-bo-chung-muon-toc" tabindex="-1">6. Chỉ số đo lường Tiến bộ chung Muôn tộc <a class="header-anchor" href="#_6-chi-so-đo-luong-tien-bo-chung-muon-toc" aria-label="Permalink to &quot;6. Chỉ số đo lường Tiến bộ chung Muôn tộc&quot;">​</a></h2><p>Văn minh cộng sinh đã xây dựng &quot;Chỉ số Tiến bộ chung Muôn tộc&quot;, đo lường tiến độ của tiến bộ chung Muôn tộc từ các chiều sau:</p><table tabindex="0"><thead><tr><th>Chiều</th><th>Chỉ số</th><th>Mục tiêu</th></tr></thead><tbody><tr><td>Tỷ lệ bao phủ tiến hóa</td><td>Tỷ lệ các chủng tộc kết nối với hệ thống tu luyện</td><td>100%</td></tr><tr><td>Mức độ cân bằng cảnh giới</td><td>Hệ số chênh lệch cảnh giới trung bình của mỗi chủng tộc</td><td>Liên tục thu hẹp</td></tr><tr><td>Mật độ hợp tác</td><td>Số lượng và chiều sâu của các dự án hợp tác giữa các chủng tộc</td><td>Liên tục tăng</td></tr><tr><td>Sức sống văn hóa</td><td>Mức độ hoạt động của kế thừa và đổi mới văn hóa chủng tộc</td><td>Duy trì sự đa dạng</td></tr><tr><td>Tỷ lệ xảy ra xung đột</td><td>Tần suất xảy ra xung đột giữa các chủng tộc</td><td>Liên tục giảm</td></tr></tbody></table><h2 id="loi-ket" tabindex="-1">Lời kết <a class="header-anchor" href="#loi-ket" aria-label="Permalink to &quot;Lời kết&quot;">​</a></h2><p>Tiến bộ chung Muôn tộc là một trong những mục tiêu tối hậu của Văn minh Cộng sinh Neo và cũng là điều kiện cần thiết cho sự thăng chiều toàn cục của vũ trụ. Trong khuôn khổ văn minh cộng sinh, mỗi chủng tộc đều có thể tìm thấy con đường tiến hóa phù hợp với bản thân, và sự độc đáo của mỗi chủng tộc đều được tôn trọng và phát huy. Tiến bộ chung Muôn tộc không phải là xóa bỏ sự khác biệt, mà là đạt được sự hài hòa trong sự khác biệt và thực hiện cộng sinh trong sự đa dạng.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (Tuyên ngôn Văn minh Cộng sinh Neo)</li><li>50-万族谱系总览 (Tổng quan Phả hệ Muôn tộc)</li><li>77-万族共和成立 (Thành lập Cộng hòa Muôn tộc)</li></ul>',32)])])}const s=c(g,[["render",a]]);export{b as __pageData,s as default};
